<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Str;
class Booking extends Model{use \App\Models\Concerns\RecordsActivity;protected $fillable=['reference','tour_id','tour_departure_id','pickup_point_id','type','status','first_name','last_name','phone','email','whatsapp','date_of_birth','age','address','participant_count','seat_count','comments','special_requests','mobility_information','food_allergies','meal_selection','promo_code','source','emergency_contact_name','emergency_contact_phone','roommate_request','currency','tax_included','total_amount','deposit_amount','amount_paid','payment_status','balance_due_date','payment_terms_note','payment_proof','policies_accepted_at','terms_accepted_at','privacy_accepted_at','marketing_consent','waiver_accepted_at','waiver_text','internal_notes','submission_token','confirmation_sent_at','confirmed_notice_sent_at','seat_notice_sent_at','updated_by'];public const STATUSES=['new'=>'New','payment_pending'=>'Payment pending','confirmed'=>'Confirmed','cancelled'=>'Cancelled','completed'=>'Completed','contacted'=>'Contacted'];public const PAYMENT_STATUSES=['unpaid'=>'Unpaid','proof_submitted'=>'Pending verification','partially_paid'=>'Partially paid','deposit_paid'=>'Deposit paid','paid'=>'Fully paid','complimentary'=>'Complimentary','refunded'=>'Refunded'];protected $casts=['date_of_birth'=>'date','age'=>'integer','total_amount'=>'decimal:2','deposit_amount'=>'decimal:2','amount_paid'=>'decimal:2','policies_accepted_at'=>'datetime','terms_accepted_at'=>'datetime','privacy_accepted_at'=>'datetime','waiver_accepted_at'=>'datetime','marketing_consent'=>'boolean','tax_included'=>'boolean','confirmation_sent_at'=>'datetime','seat_notice_sent_at'=>'datetime','confirmed_notice_sent_at'=>'datetime','balance_due_date'=>'date','discount_amount'=>'decimal:2','refunded_amount'=>'decimal:2','pending_amount'=>'decimal:2','outstanding_amount'=>'decimal:2'];protected static function booted():void{static::creating(function($m){$m->reference??='DT-'.strtoupper(Str::random(8));/* Every booking and request belongs to a customer record (found by email or phone, else created). */$m->customer_id??=\App\Support\Customers::forBooking($m)->id;/* Bookings without a seat count of their own (enquiries) take one seat per passenger. */$m->seat_count??=(int)$m->participant_count;});
  // Any change to who is travelling on which date re-counts that date's seats (and the old date's, if moved).
  /* Money figures follow the price, status, deposit and due date. */static::created(fn(Booking $b)=>\App\Support\BookingMoney::sync($b));static::updated(function(Booking $b){if($b->wasChanged(['total_amount','status','deposit_amount','balance_due_date','tour_departure_id']))\App\Support\BookingMoney::sync($b);});
  static::saved(function(Booking $b){if($b->wasChanged(['status','participant_count','seat_count','tour_departure_id'])||$b->wasRecentlyCreated){TourDeparture::find($b->tour_departure_id)?->recountSeats();if($b->wasChanged('tour_departure_id'))TourDeparture::find($b->getOriginal('tour_departure_id'))?->recountSeats();}});
  static::deleted(fn(Booking $b)=>TourDeparture::find($b->tour_departure_id)?->recountSeats());}
 public function customer(){return $this->belongsTo(Customer::class);}public function updatedBy(){return $this->belongsTo(User::class,'updated_by');} /** Exact legal document versions the customer accepted. */ public function legalAcceptances(){return $this->belongsToMany(LegalDocumentVersion::class,'booking_legal_acceptances')->withPivot('accepted_at')->with('document');}public function tour(){return $this->belongsTo(Tour::class);}public function departure(){return $this->belongsTo(TourDeparture::class,'tour_departure_id');}public function pickupPoint(){return $this->belongsTo(PickupPoint::class);}public function passengers(){return $this->hasMany(BookingPassenger::class)->orderBy('room_number')->orderBy('id');} /** True when the passengers on this booking board at different pickup points. */ public function hasMixedPickups(): bool{return $this->passengers->pluck('pickup_point_id')->filter()->unique()->count()>1;} /* Computed from the payment ledger by BookingMoney::sync(), never typed. */public function getBalanceDueAttribute(): float{return (float)$this->outstanding_amount;}public function payments(){return $this->hasMany(BookingPayment::class)->orderBy('paid_on')->orderBy('id');}public function adjustments(){return $this->hasMany(BookingAdjustment::class)->orderBy('id');}}
